mapper.select:
select
con.Con_Name as conName, cm1.C_Name as caCName, u1.U_Name as caUserName, mn.* from SYS_Contract_Authority mn left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on con.Con_Project_Id=pro.P_ID left join Sys_Company cm1 on cm1.C_id=mn.Ca_C_Id left join Sys_User u1 on u1.U_id=mn.Ca_User_Id
${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.Ca_User_Id=#{params.caUserId}
and mn.Ca_C_Id=#{params.caCId}
and con.Con_Project_Id=#{params.pId}
and INSTR(mn.Ca_Create_Uname,#{params.caCreateUname})
and INSTR(con.Con_Name,#{params.conName})
and INSTR(u1.U_Name,#{params.caUserName})
and likePname(#{params.pName},pro.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(cm1.C_Name,#{params.caCName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ca_Create_Time desc
